import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] stack = new long[n]; // prices to the right, non-decreasing from top
        int top = 0;
        boolean[] full = new boolean[n];
        int fullCount = 0;
        long total = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && stack[top - 1] > a[i]) top--;
            if (top > 0) total += a[i] - stack[top - 1];
            else {
                total += a[i];
                full[i] = true;
                fullCount++;
            }
            stack[top++] = a[i];
        }
        StringBuilder out = new StringBuilder();
        out.append(total).append('\n').append(fullCount);
        for (int i = 0; i < n; i++) if (full[i]) out.append(' ').append(i);
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	stack := []int64{} // prices to the right, non-decreasing from top
	full := []int{}
	var total int64
	for i := n - 1; i >= 0; i-- {
		for len(stack) > 0 && stack[len(stack)-1] > a[i] {
			stack = stack[:len(stack)-1]
		}
		if len(stack) > 0 {
			total += a[i] - stack[len(stack)-1]
		} else {
			total += a[i]
			full = append(full, i)
		}
		stack = append(stack, a[i])
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.FormatInt(total, 10) + "\n" + strconv.Itoa(len(full)))
	for i := len(full) - 1; i >= 0; i-- {
		w.WriteString(" " + strconv.Itoa(full[i]))
	}
	w.WriteByte('\n')
}
